288	    if (rebase.status !== 0) {
289	      const open = inProgress(gitOut(source.path, ["rev-parse", "--path-format=absolute", "--git-dir"]));
290	      if (!open) throw new WorktreeError(`rebase onto ${shownBranch(targetName)} failed: ${redactSecrets(rebase.stderr.trim().split("\n")[0] ?? "")}`);
291	      const files = git(source.path, ["diff", "--name-only", "--diff-filter=U"], { allowFailure: true }).stdout.split("\n").filter(Boolean).slice(0, 10);
292	      return {
293	        success: false,
294	        output: `Rebase onto ${shownBranch(targetName)} stopped on conflicts${files.length ? ` in ${files.map((f) => redactSecrets(f)).join(", ")}` : ""}.\n` +
295	          `The rebase is left open in ${shownPath(ctx.home, source.path)}: resolve the files, run \`git rebase --continue\` there and merge again, or \`git rebase --abort\` to undo it. ${targetName} was not changed.`,
296	      };
297	    }
298	    notes.push(`Rebased onto ${shownBranch(targetName)}.`);
299	  }
300	
301	  if (!cancelled) {
302	    // Another terminal may have switched the target checkout since it was chosen: never advance another branch under this name.
303	    const targetRef = git(targetEntry.path, ["symbolic-ref", "--quiet", "HEAD"], { allowFailure: true }).stdout.trim();
304	    if (targetRef !== `refs/heads/${targetName}`) {
305	      const targetNow = targetRef.replace(/^refs\/heads\//, "");
306	      throw new WorktreeError(`the target checkout ${shownPath(ctx.home, targetEntry.path)} is no longer on ${shownBranch(targetName)} (it is on ${targetNow ? shownBranch(targetNow) : "a detached HEAD"}); nothing was fast-forwarded. The source branch is intact and backed up at ${backupRef(branch)}; switch the target back and run merge again`);
307	    }
308	    // `refs/heads/<branch>`, not the short name: a tag of the same name would otherwise be what gets merged.
309	    // `--no-overwrite-ignore` prevents fast-forwarding over an untracked ignored file in the target.
310	    const ff = git(targetEntry.path, ["merge", "--ff-only", "--no-edit", "--no-overwrite-ignore", "--end-of-options", `refs/heads/${branch}`], { allowFailure: true, env: NON_INTERACTIVE });
311	    if (ff.status !== 0) {
312	      const errDetail = ff.stderr ? redactSecrets(ff.stderr.trim().split("\n")[0] ?? "") : "";
313	      if (errDetail && (errDetail.toLowerCase().includes("overwrite") || errDetail.toLowerCase().includes("untracked working tree file"))) {
314	        throw new WorktreeError(`could not fast-forward ${shownBranch(targetName)} to ${shownBranch(branch)}: ${errDetail}`);
315	      }
316	      throw new WorktreeError(`could not fast-forward ${shownBranch(targetName)} to ${shownBranch(branch)}: ${options.noRebase ? "the branch is not a descendant of the target (merge without --no-rebase)" : "the target moved while merging; run merge again"}`);
317	    }
318	    notes.push(`Fast-forwarded ${shownBranch(targetName)}.`);
319	  }
320	
321	  if (waiver !== undefined) {
322	    const reason = waiver;
323	    try {
324	      updateRegistry(repo.commonDir, (reg) => {
325	        reg.waivers = [...(reg.waivers ?? []), { branch, head: gateState.head, reason, recordedAt: new Date().toISOString() }].slice(-MAX_RECORDS);
326	      });
327	    } catch (err) {
328	      // The target has already advanced: report the merge, and say the audit record is missing.
329	      notes.push(`The waiver could not be recorded in the registry (${redactSecrets((err as Error).message).slice(0, 150)}).`);
330	    }
331	  }
332	
333	  if (!options.noRemove) {
334	    // The merged work is on the target. Only ignored output (build caches) may still be in the worktree; it goes with
335	    // it. Anything else left (edits inside a submodule cannot be committed from here, for one) is never forced away.
336	    let left: ReturnType<typeof statusOf>;
337	    let initialized: string[];
338	    let unpublished: string[];
339	    try {
340	      left = statusOf(source.path, { ignoreSubmodules: "none" });
341	      initialized = left.total > 0 ? [] : initializedSubmodules(source.path); // one `git submodule status` for both notes
342	      unpublished = unpublishedSubmodules(source.path, initialized);
343	    } catch (err) {
344	      // The merge is done; whatever stops the safety checks keeps the worktree rather than failing the report.
345	      left = { staged: 0, modified: 0, untracked: 0, conflicted: 0, ignored: 0, total: 1 };
346	      initialized = [];
347	      unpublished = [];
348	      notes.push(`Could not inspect the worktree after the merge (${redactSecrets((err as Error).message).slice(0, 150)}).`);
349	    }
350	    if (unpublished.length > 0) {
351	      notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: submodule ${unpublished.map((sub) => redactSecrets(sub)).join(", ")} has a commit that is on no remote branch, and removing the worktree would delete its only copy. Push it from there, then run \`worktree remove\`. The merge itself is done.`);
352	    } else if (left.total > 0) {
353	      notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: ${left.total} uncommitted change(s) remain that the merge could not carry (check \`git status\` there, submodules included). Nothing was deleted.`);
354	    } else if (initialized.length > 0) {
355	      notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: submodule ${initialized.map((sub) => redactSecrets(sub)).join(", ")} is initialized here; removing it requires \`worktree remove --force\` after verifying submodule state. The merge itself is done.`);
356	    } else {
357	      try {
358	        notes.push(removeOne({ ...ctx, cwd: targetEntry.path }, source.path, { discardIgnored: true, target: targetName }));
359	      } catch (err) {
360	        notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: removal failed (${redactSecrets((err as Error).message).slice(0, 150)}). The merge itself is done.`);
361	      }
362	    }
363	  }
364	
365	  const removedPath = !fs.existsSync(source.path) ? source.path : undefined;
366	  return { success: true, output: notes.join("\n"), data: { branch, target: targetName, targetPath: targetEntry.path, ...(removedPath ? { removedPath } : {}) } };
367	}
368	
369	// ---- prune ----------------------------------------------------------------------------------------------------
370	
371	export interface PruneOptions { dryRun?: boolean; minAgeMs?: number; limit?: number; discardIgnored?: boolean }
372	
373	const DAY_MS = 86_400_000;
374	const REPORT_LINES = 40;
375	
376	export function parseAge(text: string): number {
377	  const match = /^(\d+)([smhdw])$/.exec(text);
378	  if (!match) throw new WorktreeError("--min-age must look like 30m, 12h, 1d or 2w");
379	  const unit = { s: 1000, m: 60_000, h: 3_600_000, d: DAY_MS, w: 7 * DAY_MS }[match[2] as "s"];
380	  return Number(match[1]) * unit;
381	}
382	
383	export function pruneWorktrees(ctx: WorktreeContext, options: PruneOptions = {}): CommandResult {
384	  const minAge = options.minAgeMs ?? DAY_MS;
385	  const limit = Math.max(1, options.limit ?? 100);
386	  const repo = openRepo(ctx.cwd);
387	  const here = currentEntry(repo);
388	  const target = defaultBranch(repo);
389	  const targetSha = target ? resolveBranchCommit(repo, target) : undefined;
390	  if (!targetSha) throw new WorktreeError("this repository has no default branch to compare against");
391	
392	  const lines: string[] = [];
393	  const counts = { removed: 0, kept: 0, young: 0, stale: 0 };
394	  let limited = false;
395	  const label = (entry: WorktreeEntry) => (entry.branch ? shownBranch(entry.branch) : shownPath(ctx.home, entry.path));
396	  const keep = (entry: WorktreeEntry, why: string) => { counts.kept++; lines.push(`kept ${label(entry)}: ${why}`); };
397	  const now = Date.now();
398	
399	  for (const entry of repo.entries) {
400	    if (entry.isMain || entry === here) continue;
401	    if (counts.removed >= limit) { limited = true; break; }
402	    if (entry.prunable && entry.locked) { keep(entry, "stale but locked"); continue; }
403	    if (entry.prunable) {
404	      // A hand-deleted worktree is judged like any other. A detached one may hold the only reference to commits in its
405	      // administrative HEAD and reflog, so it goes only if that HEAD is integrated and old enough; a branch worktree's
406	      // commits live on its branch, which stays. Only the selected entries are cleared, never a global `worktree prune`.
407	      try {
408	        const stamp = Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000;
409	        if (entry.detached && now - stamp < minAge) { counts.young++; continue; }
410	        const reason = entry.detached ? integratedReason(repo, entry.head, targetSha) : "branch kept";
411	        if (!reason) { keep(entry, `stale, but its detached HEAD is not merged into ${shownBranch(target!)}`); continue; }
412	        if (!options.dryRun) clearStaleEntry(repo, entry);
413	        counts.stale++;
414	        counts.removed++;
415	        lines.push(`${options.dryRun ? "would clear" : "cleared"} stale ${label(entry)} (${reason})`);
416	      } catch (err) {
417	        keep(entry, redactSecrets((err as Error).message).slice(0, 160));
418	      }
419	      continue;
420	    }
421	    if (entry.locked) { keep(entry, "locked"); continue; }
422	    if (isSpeculativeEntry(repo, entry)) { keep(entry, "speculative task worktree"); continue; }
423	    try {
424	      const touched = Math.max(fs.statSync(entry.path).mtimeMs, Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000);
425	      if (now - touched < minAge) { counts.young++; continue; }
426	      const reason = integratedReason(repo, entry.head, targetSha);
427	      if (!reason) { keep(entry, `not merged into ${shownBranch(target!)}`); continue; }
428	      const dirty = statusOf(entry.path, { ignored: true, ignoreSubmodules: "none" });
429	      if (dirty.total > 0) { keep(entry, `dirty (${dirty.staged + dirty.modified} changed, ${dirty.untracked} untracked)`); continue; }
430	      if (dirty.ignored > 0 && !options.discardIgnored) { keep(entry, `${dirty.ignored} ignored path(s); pass --discard-ignored to prune it anyway`); continue; }
431	      if (options.dryRun) {
432	        counts.removed++;
433	        lines.push(`would remove ${label(entry)} (integrated: ${reason})`);
434	        continue;
435	      }
436	      removeOne(ctx, entry.path, { discardIgnored: dirty.ignored > 0 });
437	      counts.removed++;
438	      lines.push(`removed ${label(entry)} (integrated: ${reason})`);
439	    } catch (err) {
440	      keep(entry, redactSecrets((err as Error).message).slice(0, 160));
441	    }
442	  }
443	
444	  const summary = `${options.dryRun ? "Would remove" : "Removed"} ${counts.removed}, kept ${counts.kept}, ${counts.young} younger than the minimum age${counts.stale ? `, ${counts.stale} stale registration(s) ${options.dryRun ? "would be pruned" : "pruned"}` : ""}.`;
445	  const shown = lines.slice(0, REPORT_LINES);
446	  if (lines.length > REPORT_LINES) shown.push(`... ${lines.length - REPORT_LINES} more lines`);
447	  if (limited) shown.push(`stopped at the limit of ${limit} removals; run prune again for more`);
448	  return { success: true, output: [...shown, summary].join("\n"), data: { ...counts, limited } };
449	}
