    execFileSync("git", args, { cwd: workspace, encoding: "utf-8", stdio: ["ignore", "pipe", "ignore"] }).trim();
  try {
    return run(["rev-parse", "--abbrev-ref", "HEAD"]);
  } catch {
    return run(["symbolic-ref", "--short", "HEAD"]);
  }
}

export function getGitInfo(workspace: string): GitInfo {
  try {
    assertTrustedCheckout(workspace);
    const branch = currentBranch(workspace);

    const statusOut = workspaceStatus(workspace, "--porcelain").trim();

    const lines = statusOut ? statusOut.split("\n") : [];
    const dirtyCount = lines.length;

    const formattedBadge = dirtyCount > 0 ? `${branch} *${dirtyCount}` : branch;

    return {
      isRepo: true,
      branch,
      dirtyCount,
      formattedBadge,
    };
  } catch {
    return {
      isRepo: false,
      branch: "",
      dirtyCount: 0,
      formattedBadge: "",
    };
  }
}

export function getProjectRules(workspace: string): string | null {
  const candidates = [
    "AGENTS.md",
    "CLAUDE.md",
    "CODEX.md",
    ".nexusrules",
  ];

  for (const filename of candidates) {
    const fullPath = path.join(workspace, filename);
    if (fs.existsSync(fullPath)) {
      try {
        const content = fs.readFileSync(fullPath, "utf-8").trim();
        if (content) {
          return `### Project Instructions (loaded from ${filename}):\n${content}`;
        }
      } catch {
        // ignore read error
      }
    }
  }
